// Ternary Operator: Condition ? True_Value : False_Value

int value = 50;

// Basic Conditional Assignment
int setting = (value > 100) ? 1 : 0;
// setting is 0

// Return or Expression Evaluation
float fee = 10.0f;
float final_fee = (value < 60) ? fee * 0.5f : fee;
// final_fee is 5.0f

// Caution: Requires compatible types
// Both branches must yield types convertible to the assignment type.
bool is_active = true;
int status_code = is_active ? 200 : 404;
